'use client';

import { useState } from 'react';

/**
 * Sample scene of a style, generated by apps/api/scripts/style-samples.ts into
 * public/styles. Until it exists the card shows the style name instead of an
 * image from another style.
 */
export function StyleSample({ id, name, className = '' }: { id: string; name: string; className?: string }) {
  const [missing, setMissing] = useState(false);
  if (missing) {
    return (
      <span className="absolute inset-0 grid place-items-center bg-gradient-to-br from-white/10 to-white/[0.02] px-6 text-center font-display text-2xl text-mist">
        {name}
      </span>
    );
  }
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={`/styles/${id}.jpg`}
      alt={`Exemplo do estilo ${name}`}
      className={`h-full w-full object-cover ${className}`}
      onError={() => setMissing(true)}
    />
  );
}
